/*
 * Regenerate every scenario's Playwright code from its stored DSL, so scenarios
 * created before a template change pick up new evidence features (per-step
 * snapshots, failure banners, ...) without being opened and re-generated by hand.
 *
 * SAFE BY DEFAULT: runs a dry-run and writes nothing unless you pass --apply.
 * On --apply it first writes a JSON backup of every old generated_code so the
 * change can be rolled back.
 *
 * Usage (run where the server's .env / Supabase keys are available):
 *   node scripts/regen-scenarios.js              # dry-run: report only
 *   node scripts/regen-scenarios.js --limit 5    # dry-run on the first 5
 *   node scripts/regen-scenarios.js --apply      # write, after backing up
 *
 * It does NOT try to detect hand-edited scripts (there is no such marker in the
 * data). The backup file is your rollback if a manual edit gets overwritten.
 */
'use strict';
require('dotenv/config');

const fs = require('fs');
const path = require('path');
const { canRegenerate, toGeneratorInput } = require('../dist/server/services/regen-service.js');
const { CodeGenerator } = require('../dist/generator/code-generator.js');
const { supabase } = require('../dist/server/supabase-client.js');

const args = process.argv.slice(2);
const APPLY = args.includes('--apply');
const limitArg = args.indexOf('--limit');
const LIMIT = limitArg !== -1 ? parseInt(args[limitArg + 1], 10) : null;

async function main() {
  console.log(`\nRegenerate scenarios — mode: ${APPLY ? 'APPLY (will write)' : 'DRY-RUN (no writes)'}${LIMIT ? `, limit ${LIMIT}` : ''}\n`);

  // Pull every scenario's regeneration inputs. flow_history is the scenario store.
  let query = supabase
    .from('flow_history')
    .select('id, test_suite, generated_code, resolved_steps, raw_dsl')
    .order('timestamp', { ascending: true });
  if (LIMIT) query = query.limit(LIMIT);

  const { data, error } = await query;
  if (error) {
    console.error('Failed to read flow_history:', error.message || error);
    process.exit(1);
  }
  const rows = data || [];
  console.log(`Read ${rows.length} scenario record(s).`);

  const gen = new CodeGenerator();
  const backup = [];
  let changed = 0;
  let unchanged = 0;
  let skipped = 0;

  for (const row of rows) {
    const record = {
      testSuite: row.test_suite,
      resolvedSteps: row.resolved_steps,
      rawDsl: row.raw_dsl
    };
    const guard = canRegenerate(record);
    if (!guard.ok) {
      skipped++;
      console.log(`  SKIP ${row.id} (${row.test_suite}): ${guard.reason}`);
      continue;
    }

    const { config, resolvedSteps } = toGeneratorInput(record);
    let newCode;
    try {
      const result = await gen.generateScript(config, resolvedSteps);
      newCode = typeof result === 'string' ? result : result.code;
    } catch (e) {
      skipped++;
      console.log(`  SKIP ${row.id} (${row.test_suite}): generate error: ${e.message}`);
      continue;
    }

    const oldCode = row.generated_code || '';
    if (newCode === oldCode) {
      unchanged++;
      continue;
    }

    changed++;
    const oldLen = oldCode.length;
    const newLen = newCode.length;
    console.log(`  ${APPLY ? 'WRITE' : 'WOULD CHANGE'} ${row.id} (${row.test_suite}): ${oldLen} -> ${newLen} bytes`);

    if (APPLY) {
      backup.push({ id: row.id, testSuite: row.test_suite, oldGeneratedCode: oldCode });
      const { error: upErr } = await supabase
        .from('flow_history')
        .update({ generated_code: newCode, status: 'GENERATED' })
        .eq('id', row.id);
      if (upErr) {
        console.error(`    FAILED to write ${row.id}: ${upErr.message || upErr}`);
      }
    }
  }

  if (APPLY && backup.length > 0) {
    const backupPath = path.join(process.cwd(), `regen-backup-${Date.now()}.json`);
    fs.writeFileSync(backupPath, JSON.stringify(backup, null, 2), 'utf-8');
    console.log(`\nBackup of ${backup.length} old script(s) written to ${backupPath}`);
    console.log('Rollback: for each entry, update flow_history.generated_code back to oldGeneratedCode.');
  }

  console.log(`\nSummary: ${changed} changed, ${unchanged} unchanged, ${skipped} skipped, ${rows.length} total.`);
  if (!APPLY && changed > 0) console.log('Dry-run only. Re-run with --apply to write these changes.');
  console.log('');
}

main().catch((e) => { console.error('regen failed:', e); process.exit(1); });
